<script setup lang="ts">
import {ref,onMounted} from 'vue';import {t,translateMessage,type Locale,type MessageKey} from '../shared/i18n';import type {ReadinessReport,ReadinessCheck} from '../shared/readiness';
const props=defineProps<{locale:Locale}>(),emit=defineEmits<{navigate:[action:ReadinessCheck['action']]}>();const report=ref<ReadinessReport>(),busy=ref(false),error=ref('');
async function refresh(){busy.value=true;error.value='';try{report.value=await window.studio.preflight();}catch(e){error.value=String(e instanceof Error?e.message:e);}finally{busy.value=false;}}
onMounted(refresh);
</script>
<template><section class="card setup-panel"><div class="card-toolbar"><h2>{{t(locale,'setup.title')}}</h2><button :disabled="busy" @click="refresh">{{t(locale,busy?'setup.checking':'common.refresh')}}</button></div><p>{{t(locale,'setup.intro')}}</p><p v-if="error" role="alert">{{translateMessage(locale,error)}}</p><ol v-if="report"><li v-for="check in report.checks" :key="check.id"><span class="check-state" :class="{done:check.ready}">{{check.ready?'✓':'○'}}</span><div><b>{{check.provider?check.provider.toUpperCase()+' · ':''}}{{t(locale,check.key as MessageKey)}}</b><small>{{t(locale,check.ready?'setup.ready':check.required?'setup.required':'setup.optional')}}</small></div><button v-if="!check.ready" @click="emit('navigate',check.action)">{{t(locale,'setup.configure')}}</button></li></ol><p v-if="report" class="setup-result">{{t(locale,report.canStream?'setup.streamReady':'setup.streamBlocked')}} · {{t(locale,report.canHost?'setup.hostReady':'setup.hostBlocked')}}</p><p class="hint">{{t(locale,'setup.privacy')}}</p></section></template>
<style scoped>.setup-panel{max-width:980px;padding-bottom:24px}.setup-panel>p{margin:12px 25px;color:#80738f;font-size:12px;line-height:1.8}ol{list-style:none;padding:0 25px;margin:0}li{display:flex;align-items:center;gap:15px;padding:17px 0;border-bottom:1px solid #eee9f4}li>div{flex:1}b{font-size:13px;color:#675875}small{display:block;font-size:11px;color:#9a899f;margin-top:6px}.check-state{display:grid;place-items:center;border-radius:50%;width:28px;height:28px;background:#f1edf7;color:#aa8fb4}.check-state.done{background:#e6f5ef;color:#398a68}.setup-result{background:#f3eff9;padding:15px;border-radius:12px}</style>
